const input = $json ?? {};
const hasProjectInput = Object.prototype.hasOwnProperty.call(input, 'project_id');

if (!hasProjectInput) {
  return [{
    json: {
      route: 'reconciliation',
      project_id: null,
      scan_mode: 'single_url',
      max_pages: 1
    }
  }];
}

const projectId = Number(input.project_id);
if (!Number.isInteger(projectId) || projectId <= 0) {
  throw new Error('WDC-013 input non valido: project_id deve essere un intero maggiore di zero');
}

return [{
  json: {
    route: 'event',
    project_id: projectId,
    scan_mode: 'single_url',
    max_pages: 1
  }
}];

const source = $json;
const isEvent = source.route === 'event';

const cutoff = new Date(Date.now() - 5 * 24 * 60 * 60 * 1000)
  .toISOString()
  .slice(0, 19)
  .replace('T', ' ');

const domain = [
  ['active', '=', true],
  ['x_studio_wdc008_production_url', '!=', false],
];

if (isEvent) {
  domain.push(['id', '=', source.project_id]);
} else {
  domain.push(
    '|',
    ['x_studio_wdc013_last_audit_at', '=', false],
    ['x_studio_wdc013_last_audit_at', '<=', cutoff],
  );
}

return [{
  json: {
    route: source.route,
    requested_project_id: source.project_id,
    scan_mode: source.scan_mode,
    max_pages: source.max_pages,
    domain,
    fields: [
      'id',
      'name',
      'active',
      'x_studio_wdc008_production_url',
      'x_studio_wdc013_accessibility_status',
      'x_studio_wdc013_accessibility_score',
      'x_studio_wdc013_wcag_issues',
      'x_studio_wdc013_recommendations',
      'x_studio_wdc013_last_audit_at',
      'x_studio_wdc013_report_url',
      'x_studio_wdc013_hash'
    ],
    limit: isEvent ? 1 : 100,
    order: 'x_studio_wdc013_last_audit_at asc, id asc'
  }
}];

const project = $json;
if (!project?.id) return [];

const rawUrl = String(project.x_studio_wdc008_production_url || '').trim();
if (!rawUrl) return [];

let parsed;
try {
  parsed = new URL(rawUrl);
} catch {
  throw new Error(`WDC-013 progetto ${project.id}: URL produzione non valido: ${rawUrl}`);
}

if (!['http:', 'https:'].includes(parsed.protocol)) {
  throw new Error(`WDC-013 progetto ${project.id}: protocollo URL non supportato`);
}

const origin = $('01 - Normalize & Validate Input').item.json;

return [{
  json: {
    project_id: project.id,
    project_name: project.name || `Progetto ${project.id}`,
    target_url: parsed.toString(),
    external_ref: `odoo-project-${project.id}`,
    scan_mode: origin.scan_mode || 'single_url',
    max_pages: origin.max_pages || 1,
    previous_hash: project.x_studio_wdc013_hash || null,
    previous_score: project.x_studio_wdc013_accessibility_score ?? null,
    previous_last_audit_at: project.x_studio_wdc013_last_audit_at || null
  }
}];

const response = $json;
const source = $('04 - Prepare Scanner Request').item.json;

if (!response?.job_id) {
  throw new Error('WDC-013: lo scanner non ha restituito job_id');
}
if (!['queued', 'running'].includes(String(response.status || ''))) {
  throw new Error(`WDC-013: stato iniziale scanner inatteso: ${response.status}`);
}

return [{
  json: {
    ...response,
    project_id: source.project_id,
    project_name: source.project_name,
    target_url: source.target_url,
    external_ref: source.external_ref
  }
}];

const job = $json;
if (!job?.job_id) throw new Error('WDC-013 polling: job_id mancante');

const status = String(job.status || '').trim();

if (status === 'completed') {
  const result = job.result;
  if (!result || result.schema_version !== 'wdc013.a11y-result.v1') {
    return [{
      json: {
        ...job,
        status: 'failed',
        route: 'failed',
        error: `schema_runtime_non_valido:${result?.schema_version || 'missing'}`
      }
    }];
  }

  const w = result.wdc013;
  const allowed = new Set(['not_checked', 'good', 'issues_found', 'critical', 'blocked']);
  if (!w || !allowed.has(String(w.odoo_status_key || ''))) {
    return [{
      json: {
        ...job,
        status: 'failed',
        route: 'failed',
        error: `odoo_status_non_valido:${w?.odoo_status_key || 'missing'}`
      }
    }];
  }

  return [{ json: { ...job, route: 'completed' } }];
}

if (status === 'failed') {
  return [{ json: { ...job, route: 'failed' } }];
}

const createdAt = Date.parse(job.created_at || '');
if (Number.isFinite(createdAt) && Date.now() - createdAt > 16 * 60 * 1000) {
  return [{
    json: {
      ...job,
      status: 'failed',
      route: 'failed',
      error: 'poll_timeout_oltre_16_minuti'
    }
  }];
}

if (!['queued', 'running'].includes(status)) {
  return [{
    json: {
      ...job,
      status: 'failed',
      route: 'failed',
      error: `stato_scanner_inatteso:${status || 'missing'}`
    }
  }];
}

return [{ json: { ...job, route: 'wait' } }];

const job = $json;
const result = job.result;
const w = result?.wdc013;

const ref = String(job.meta?.external_ref || result?.external_ref || '');
const match = ref.match(/^odoo-project-(\d+)$/);
if (!match) throw new Error(`WDC-013 completed: external_ref non valido: ${ref}`);

const projectId = Number(match[1]);
const odooDateTime = value => {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new Error(`WDC-013: datetime non valido: ${value}`);
  return d.toISOString().slice(0, 19).replace('T', ' ');
};

let issues = String(w.issues_text || '').trim();
const score = w.accessibility_score;

const vals = {
  x_studio_wdc013_accessibility_status: w.odoo_status_key,
  x_studio_wdc013_wcag_issues: issues,
  x_studio_wdc013_recommendations: String(w.recommendations_text || ''),
  x_studio_wdc013_last_audit_at: odooDateTime(w.last_audit_at || result.generated_at),
  x_studio_wdc013_report_url: String(w.report_url || result.report?.html_url || ''),
  x_studio_wdc013_hash: String(w.audit_hash || result.audit_hash || '')
};

if (Number.isInteger(score) && score >= 0 && score <= 100) {
  vals.x_studio_wdc013_accessibility_score = score;
} else {
  vals.x_studio_wdc013_wcag_issues = [
    '[WDC-013] Score corrente non conclusivo: il campo Accessibility Score non viene sovrascritto.',
    issues
  ].filter(Boolean).join('\n');
}

return [{
  json: {
    project_id: projectId,
    scanner_status: result.status,
    audit_hash: vals.x_studio_wdc013_hash,
    vals
  }
}];

const job = $json;
const ref = String(job.meta?.external_ref || job.external_ref || '');
const match = ref.match(/^odoo-project-(\d+)$/);
if (!match) throw new Error(`WDC-013 failed: external_ref non valido: ${ref}`);

const projectId = Number(match[1]);
const error = String(job.error || 'scanner_failed');

return [{
  json: {
    project_id: projectId,
    vals: {
      x_studio_wdc013_accessibility_status: 'blocked',
      x_studio_wdc013_wcag_issues: `[WDC-013][SCANNER BLOCKED] ${error}`,
      x_studio_wdc013_recommendations: 'Verificare il servizio Accessibility Scanner Cloud e rilanciare il controllo. L’ultimo audit riuscito non è stato sovrascritto.'
    }
  }
}];
